    def chat(self, model: str, messages: List[Dict[str, str]], max_tokens: int, temperature: float = 0.3) -> Dict[str, Any]:
        url = f"{self.base}/chat/completions"
        headers = {"Authorization": f"Bearer {self.key}", "Content-Type": "application/json"}
        payload = {"model": model, "messages": messages, "max_tokens": max_tokens, "temperature": temperature}
        for attempt in range(5):
            try:
                r = requests.post(url, headers=headers, data=json.dumps(payload), timeout=180)
                if r.status_code == 200:
                    return r.json()
                time.sleep(2 ** attempt)
            except Exception:
                time.sleep(2 ** attempt)
        raise HTTPException(status_code=502, detail="XAI chat error")

class ExaClient:
    def __init__(self, base: str, api_key: str):
        self.base = base.rstrip("/")
        self.key = api_key

    def search(self, query: str, num_results: int = 100, language: Optional[str] = None) -> List[Dict[str, Any]]:
        url = f"{self.base}/search"
        headers = {"x-api-key": self.key, "Content-Type": "application/json"}
        payload = {"query": query, "numResults": num_results, "text": True}
        if language:
            payload["language"] = language
        r = requests.post(url, headers=headers, data=json.dumps(payload), timeout=60)
        if r.status_code == 200:
            data = r.json()
            return data.get("results", [])
        raise HTTPException(status_code=502, detail=f"Exa search error {r.status_code}")

    def webset_create(self, query: str, count: int) -> Dict[str, Any]:
        url = f"{self.base}/websets/v0/websets"
        headers = {"x-api-key": self.key, "Content-Type": "application/json"}
        payload = {"search": {"query": query, "count": count}}
        r = requests.post(url, headers=headers, data=json.dumps(payload), timeout=60)
        if r.status_code in (200, 201):
            return r.json()
        raise HTTPException(status_code=502, detail=f"Exa webset create error {r.status_code}")

    def webset_search(self, webset_id: str, query: str, count: int) -> Dict[str, Any]:
        url = f"{self.base}/websets/v0/websets/{webset_id}/searches"
        headers = {"x-api-key": self.key, "Content-Type": "application/json"}
        payload = {"count": count, "query": query}
        r = requests.post(url, headers=headers, data=json.dumps(payload), timeout=60)
        if r.status_code == 200:
            return r.json()
        raise HTTPException(status_code=502, detail=f"Exa webset search error {r.status_code}")

