def job_create(topic: str) -> str:
    jid = strong_id()
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("INSERT INTO jobs(id,topic,status,created_at,updated_at,progress,report_path,logs) VALUES(?,?,?,?,?,?,?,?)",
                    (jid, topic, "created", now_utc(), now_utc(), 0.0, None, json.dumps([])))
        con.commit()
    return jid

def job_update(jid: str, status: Optional[str] = None, progress: Optional[float] = None, log_line: Optional[str] = None, report_path: Optional[str] = None):
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("SELECT logs FROM jobs WHERE id=?", (jid,))
        row = cur.fetchone()
        logs = json.loads(row[0]) if row and row[0] else []
        if log_line:
            logs.append(f"{datetime.datetime.utcnow().isoformat()} {log_line}")
        fields = []
        values = []
        if status is not None:
            fields.append("status=?")
            values.append(status)
        if progress is not None:
            fields.append("progress=?")
            values.append(float(clamp(progress, 0.0, 1.0)))
        if report_path is not None:
            fields.append("report_path=?")
            values.append(report_path)
        fields.append("updated_at=?")
        values.append(now_utc())
        fields.append("logs=?")
        values.append(json.dumps(logs[-500:]))
        q = f"UPDATE jobs SET {', '.join(fields)} WHERE id=?"
        values.append(jid)
        cur.execute(q, tuple(values))
        con.commit()

def job_get(jid: str) -> JobStatus:
    with sqlite3.connect(settings.db_path) as con:
        cur = con.cursor()
        cur.execute("SELECT id,topic,status,progress,updated_at,report_path,logs FROM jobs WHERE id=?", (jid,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Job not found")
    return JobStatus(id=row[0], topic=row[1], status=row[2], progress=row[3], updated_at=row[4], report_path=row[5], logs=json.loads(row[6]) if row[6] else [])

