            {"role": "user", "content": f"Téma: {topic}\nForrás: {url}\nAdj 5–8 rövid állítást JSON tömbként: [{'{'}\"claim\":\"...\",\"quote\":\"...\",\"quality\":\"strong|medium|weak\"{'}'}]."}
